def _fit(job, doc, kind):
    """연차보고서 양식 맞추기(`report_fit`) — 구분 기준 모듈로 절 · 표만 맞춘다(spec_작업 ② §16). 사업계획서는 2026-11-18 부터 _std(양식 표준화 — spec_양식표준화).
    kind = 그 문서의 첨부 파일 종류(문서 하나 = 목적 문서 — roles)."""
