    out += [_c_zones(), _C_RUNNING, _C_LLM, _C_DIVLLM, _C_ZONELLM]
    if fill:
        out.append(_c_task_llm("자리 연결 LLM 검토 · 표 대응 · 빈 자리 검토", f"단계의 단추나, 확인을 받은 {fill} 「한 번에 진행」 안에서 돕니다"))
    return tuple(out)


